{
  "name": "worktender-watch",
  "version": "0.4.1",
  "description": "Watches the worktender fleet: a status line count, a band when a worker reports done or blocked, and a toast (or, opted in, a turn) when one does.",
  "author": {
    "name": "Tom Steigerwald"
  },
  "homepage": "https://steig.github.io/worktender/watch.html",
  "repository": "https://github.com/steig/worktender",
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "wake": {
      "type": "string",
      "title": "On a new report",
      "description": "toast shows a toast and the band; turn also starts a turn so Claude verifies it (spends tokens without you asking).",
      "default": "toast",
      "options": [
        "toast",
        "turn"
      ]
    },
    "scope": {
      "type": "string",
      "title": "Which workers",
      "description": "repo watches the repository the session started in; all watches every repository herdr has workers in.",
      "default": "repo",
      "options": [
        "repo",
        "all"
      ]
    },
    "prFeedback": {
      "type": "boolean",
      "title": "Route PR feedback to workers",
      "description": "Each poll, run `worktender pr-feedback`: tell the idle worker on a branch about new reviews and failing checks on its open PR (counts, logins and check names only). One gh call per branch.",
      "default": false
    },
    "prFeedbackRounds": {
      "type": "number",
      "title": "PR feedback rounds per PR",
      "description": "How many notices one PR's worker gets before further reviews and failing checks go to you as a toast instead of to the worker. 0 sends none.",
      "default": 2
    },
    "refocus": {
      "type": "boolean",
      "title": "Refocus workers after compaction",
      "description": "In a worker's session, after Claude Code compacts it, add the goal chain from `worktender refocus` (tracking issue, issue and its acceptance criteria) to its context. Two gh calls per compaction. Also, where the worker's role sets a refocus interval, on the prompts `worktender refocus --if-due` says are due.",
      "default": true
    },
    "intervalSeconds": {
      "type": "number",
      "title": "Poll interval (seconds)",
      "description": "How often to run `worktender ls --reports --json`. It takes about 20 ms.",
      "default": 30
    },
    "worktender": {
      "type": "string",
      "title": "worktender binary",
      "description": "Path to worktender, or the name to find on PATH.",
      "default": "worktender"
    }
  }
}

